package io.github.foodjournal.application;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import io.github.foodjournal.domain.*;
import io.github.foodjournal.infrastructure.openfoodfacts.OpenFoodFactsClient;
import io.github.foodjournal.repository.*;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class JournalToolExecutor {
  private final ObjectMapper json; private final UserSettingsRepository settings; private final FoodEntryRepository entries; private final FoodItemRepository items;
  private final PrivateFoodRepository privateFoods; private final NutritionResolver nutrition; private final DailyStatusService dailyStatus; private final PendingAgentActionRepository pending;
  private final OpenFoodFactsClient packagedFoods; private final PendingNutritionQuoteRepository quotes; private final NutritionSourceCacheRepository cache;
  @org.springframework.beans.factory.annotation.Autowired public JournalToolExecutor(ObjectMapper json, UserSettingsRepository settings, FoodEntryRepository entries, FoodItemRepository items, PrivateFoodRepository privateFoods, NutritionResolver nutrition, DailyStatusService dailyStatus, PendingAgentActionRepository pending, OpenFoodFactsClient packagedFoods, PendingNutritionQuoteRepository quotes, NutritionSourceCacheRepository cache) { this.json=json;this.settings=settings;this.entries=entries;this.items=items;this.privateFoods=privateFoods;this.nutrition=nutrition;this.dailyStatus=dailyStatus;this.pending=pending;this.packagedFoods=packagedFoods;this.quotes=quotes;this.cache=cache; }
  /** Kept for focused unit tests that do not exercise quote-backed nutrition. */
  public JournalToolExecutor(ObjectMapper json, UserSettingsRepository settings, FoodEntryRepository entries, FoodItemRepository items, PrivateFoodRepository privateFoods, NutritionResolver nutrition, DailyStatusService dailyStatus, PendingAgentActionRepository pending) { this(json,settings,entries,items,privateFoods,nutrition,dailyStatus,pending,null,null,null); }

  @Transactional(noRollbackFor=AgentToolFailure.class) public AgentToolResult execute(AgentContext c, JournalAgentModel.ToolCall call, List<String> todos) {
    try { Map<String,Object> a=json.readValue(call.arguments()==null?"{}":call.arguments(),new TypeReference<>(){}); return switch(call.name()) {
      case "get_today_summary" -> today(c); case "search_entries" -> search(c,a); case "get_entry" -> entry(c,a); case "get_settings" -> settings(c);
      case "resolve_nutrition", "lookup_food" -> resolve(c,a); case "search_packaged_food" -> packagedFood(c,a); case "get_pending_nutrition_quotes" -> pendingQuotes(c);
      case "select_packaged_food" -> selectPackaged(c,a); case "get_private_food" -> privateFood(c,a); case "plan_todos" -> planTodos(a,todos); case "complete_todo" -> completeTodo(a,todos);
      case "create_food_entry" -> create(c,a); case "estimate_food" -> estimateFood(c,a); case "save_private_food" -> savePrivate(c,a); case "update_settings" -> updateSettings(c,a);
      case "prepare_entry_edit" -> prepare(c,a,"EDIT"); case "prepare_entry_delete" -> prepare(c,a,"DELETE"); case "get_pending_action" -> getPending(c); case "confirm_pending_action" -> confirm(c);
      default -> AgentToolResult.failure("VALIDATION_ERROR","That tool is not available.");
    }; } catch (JsonProcessingException | IllegalArgumentException e) { throw new AgentToolFailure(AgentToolResult.failure("VALIDATION_ERROR", "The supplied details are invalid.")); }
  }
  private AgentToolResult planTodos(Map<String,Object>a,List<String> todos){Object raw=a.get("todos");if(!(raw instanceof List<?> list))return AgentToolResult.failure("VALIDATION_ERROR","Provide a short todo list.");todos.clear();for(Object value:list)if(value!=null&&!String.valueOf(value).isBlank()&&todos.size()<6)todos.add(String.valueOf(value));return AgentToolResult.ok(Map.of("todos",List.copyOf(todos)));}
  private AgentToolResult completeTodo(Map<String,Object>a,List<String> todos){String todo=str(a,"todo");if(todo==null||!todos.remove(todo))return AgentToolResult.failure("NOT_FOUND","That todo is not in the current run.");return AgentToolResult.ok(Map.of("todos",List.copyOf(todos)));}
  private AgentToolResult today(AgentContext c){List<FoodEntry> rows=forToday(c.user());int total=rows.stream().map(FoodEntry::getCalories).filter(Objects::nonNull).mapToInt(Integer::intValue).sum();Integer target=profile(c).getCalorieTarget();return AgentToolResult.ok(Map.of("calories",total,"entries",rows.size(),"target",target==null?"unset":target));}
  private AgentToolResult search(AgentContext c,Map<String,Object>a){String q=str(a,"query");List<FoodEntry> rows=q==null?forToday(c.user()):entries.searchByUserAndTerm(c.user(),q);return AgentToolResult.ok(Map.of("entries",rows.stream().limit(10).map(this::summary).toList()));}
  private AgentToolResult entry(AgentContext c,Map<String,Object>a){return entries.findByIdAndUser(number(a,"entryId").longValue(),c.user()).<AgentToolResult>map(e->AgentToolResult.ok(Map.of("entry",summary(e)))).orElse(AgentToolResult.failure("NOT_FOUND","No matching journal entry exists."));}
  private AgentToolResult settings(AgentContext c){UserSettings s=profile(c);return AgentToolResult.ok(Map.of("timezone",s.getTimezone(),"calorieTarget",s.getCalorieTarget()==null?"unset":s.getCalorieTarget(),"reportsEnabled",s.isReportsEnabled()));}
  private AgentToolResult resolve(AgentContext c,Map<String,Object>a){JournalIntent.MealItem requested=mealItem(a);NutritionResolver.ResolvedMealItem r=nutrition.resolve(c.user(),requested);JournalIntent.MealItem i=r.item();if(i==null||i.totalCalories()==null)return AgentToolResult.failure("NOT_FOUND","Nutrition could not be resolved; search packaged food or estimate it.");return AgentToolResult.ok(Map.of("name",i.name(),"grams",i.grams(),"totalCalories",i.totalCalories(),"caloriesPer100g",i.caloriesPer100g()==null?"unknown":i.caloriesPer100g(),"source",r.source()));}
  private AgentToolResult privateFood(AgentContext c,Map<String,Object>a){String name=str(a,"name");return privateFoods.findByUserAndNameIgnoreCase(c.user(),name).<AgentToolResult>map(p->AgentToolResult.ok(Map.of("name",p.getName(),"caloriesPer100g",p.getCaloriesPer100g()))).orElse(AgentToolResult.failure("NOT_FOUND","No household food matches that name."));}
  private AgentToolResult packagedFood(AgentContext c,Map<String,Object>a){
    if(packagedFoods==null||quotes==null)return AgentToolResult.failure("TEMPORARY_FAILURE","Packaged-food search is unavailable."); String name=str(a,"name"); Double grams=decimalNumber(a,"grams");
    if(name==null||name.isBlank()||grams==null||grams<=0)return AgentToolResult.failure("VALIDATION_ERROR","A food name and positive grams are required.");
    List<Map<String,Object>> products=new ArrayList<>(); for(OpenFoodFactsClient.PackagedFoodResult p:packagedFoods.searchByName(name,str(a,"brand"))){PendingNutritionQuote q=quotes.save(PendingNutritionQuote.packaged(c.user(),p.productName(),p.brand(),grams,p.caloriesPer100g(),p.barcode(),p.sourceUrl(),Instant.now()));products.add(quoteSummary(q));}
    return products.isEmpty()?AgentToolResult.failure("NOT_FOUND","No usable packaged-food result was found."):AgentToolResult.ok(Map.of("products",products));
  }
  private AgentToolResult pendingQuotes(AgentContext c){if(quotes==null)return AgentToolResult.failure("TEMPORARY_FAILURE","Nutrition choices are unavailable.");List<Map<String,Object>> rows=quotes.findByUserAndExpiresAtAfterOrderByCreatedAtAsc(c.user(),Instant.now()).stream().map(this::quoteSummary).toList();return rows.isEmpty()?AgentToolResult.failure("NOT_FOUND","There are no pending nutrition choices."):AgentToolResult.ok(Map.of("quotes",rows));}
  private AgentToolResult selectPackaged(AgentContext c,Map<String,Object>a){PendingNutritionQuote q=ownedQuote(c,quoteId(a),PendingNutritionQuote.Type.PACKAGED_MATCH);if(q==null)return AgentToolResult.failure("NOT_FOUND","That packaged-food choice is unavailable or expired.");return AgentToolResult.ok(Map.of("quoteId",q.getId().toString(),"item",itemSummary(quoteItem(q),"open_food_facts_estimate","estimate"),"source","Open Food Facts"));}
  private AgentToolResult estimateFood(AgentContext c,Map<String,Object>a){if(quotes==null)return AgentToolResult.failure("TEMPORARY_FAILURE","Nutrition estimates are unavailable.");JournalIntent.MealItem item=mealItem(a);if(!validItem(item)||!validCaloriesPer100g(item.caloriesPer100g()))return AgentToolResult.failure("VALIDATION_ERROR","An estimate needs a food name, positive grams, and calories per 100 g between 1 and 10000.");String basis=Optional.ofNullable(str(a,"basis")).filter(v->!v.isBlank()).orElse("AI estimate");PendingNutritionQuote q=quotes.save(PendingNutritionQuote.estimate(c.user(),item.name(),item.grams(),item.caloriesPer100g(),basis,Instant.now()));return AgentToolResult.ok(Map.of("quoteId",q.getId().toString(),"item",itemSummary(quoteItem(q),"ai_estimate","estimate"),"basis",basis));}
  private AgentToolResult create(AgentContext c,Map<String,Object>a){
    List<Map<String,Object>> raw=json.convertValue(a.get("items"),new TypeReference<>(){});if(raw==null||raw.isEmpty())return AgentToolResult.failure("VALIDATION_ERROR","At least one food item is required.");List<PersistedItem> resolved=new ArrayList<>();List<PendingNutritionQuote> consumed=new ArrayList<>();
    for(Map<String,Object> row:raw){NutritionMode mode=nutritionMode(row);if(mode==NutritionMode.DECLARED){JournalIntent.MealItem requested=mealItem(row);if(!validItem(requested))return AgentToolResult.failure("VALIDATION_ERROR","Each item needs a name and a positive gram quantity.");NutritionResolver.ResolvedMealItem r=nutrition.resolve(c.user(),requested);JournalIntent.MealItem item=r.item();if(item==null||item.totalCalories()==null)return AgentToolResult.failure("VALIDATION_ERROR","One item needs calories per 100 g, total calories, a barcode, or a saved household food.");if(item.totalCalories()<=0||item.totalCalories()>10000)return AgentToolResult.failure("VALIDATION_ERROR","One item has an invalid calorie value.");resolved.add(new PersistedItem(item,"manual","high"));}
      else {PendingNutritionQuote.Type expected=mode==NutritionMode.PACKAGED_MATCH?PendingNutritionQuote.Type.PACKAGED_MATCH:PendingNutritionQuote.Type.AI_ESTIMATE;PendingNutritionQuote q=ownedQuote(c,quoteId(row),expected);if(q==null)return AgentToolResult.failure("NOT_FOUND","That nutrition quote is unavailable, expired, or belongs to another user.");JournalIntent.MealItem item=quoteItem(q);resolved.add(new PersistedItem(item,sourceFor(mode),"estimate"));consumed.add(q);}
    }
    int total=resolved.stream().map(PersistedItem::item).mapToInt(i->i.totalCalories()).sum();if(total<=0||total>10000)return AgentToolResult.failure("VALIDATION_ERROR","The meal calorie total is outside the allowed range.");String source=resolved.stream().map(PersistedItem::source).distinct().count()==1?resolved.getFirst().source():"mixed";String confidence=resolved.stream().allMatch(i->"high".equals(i.confidence()))?"high":"estimate";FoodEntry saved=entries.save(new FoodEntry(c.user(),c.message(),Instant.now(),total,source,confidence));for(PersistedItem r:resolved){JournalIntent.MealItem i=r.item();items.save(new FoodItem(saved,i.name(),BigDecimal.valueOf(i.grams()),i.totalCalories(),decimal(i.proteinGrams()),decimal(i.carbsGrams()),decimal(i.fatGrams()),r.source(),r.confidence()));}
    for(PendingNutritionQuote q:consumed){if(q.getType()==PendingNutritionQuote.Type.PACKAGED_MATCH)cacheSelected(q);quotes.delete(q);}dailyStatus.refresh(c.user(),c.chatId());return AgentToolResult.ok(Map.of("entry",summary(saved),"today",today(c).data(),"estimated",!"high".equals(confidence)));
  }
  private void cacheSelected(PendingNutritionQuote q){if(cache==null||q.getBarcode()==null||q.getBarcode().isBlank())return;NutritionSourceCache existing=cache.findByBarcode(q.getBarcode()).orElse(null);if(existing==null)cache.save(new NutritionSourceCache(q.getBarcode(),q.getProductName(),q.getCaloriesPer100g(),null,null,null,q.getSourceUrl(),Instant.now()));else existing.refresh(q.getProductName(),q.getCaloriesPer100g(),null,null,null,q.getSourceUrl(),Instant.now());}
  private PendingNutritionQuote ownedQuote(AgentContext c,UUID id,PendingNutritionQuote.Type type){if(quotes==null||id==null)return null;return quotes.lockOwnedActive(id,c.user(),Instant.now()).filter(q->q.getType()==type).orElse(null);}
  private JournalIntent.MealItem quoteItem(PendingNutritionQuote q){return withCalculatedCalories(new JournalIntent.MealItem(q.getProductName(),q.getGrams(),null,q.getCaloriesPer100g(),null,null,null,q.getBarcode()));}
  private Map<String,Object> quoteSummary(PendingNutritionQuote q){Map<String,Object> m=new LinkedHashMap<>();m.put("quoteId",q.getId().toString());m.put("name",q.getProductName());m.put("brand",q.getBrand());m.put("grams",q.getGrams());m.put("caloriesPer100g",q.getCaloriesPer100g());m.put("totalCalories",quoteItem(q).totalCalories());m.put("type",q.getType().name());if(q.getBarcode()!=null)m.put("barcode",q.getBarcode());if(q.getSourceUrl()!=null)m.put("sourceUrl",q.getSourceUrl());return m;}
  private AgentToolResult savePrivate(AgentContext c,Map<String,Object>a){String name=str(a,"name");Integer kcal=number(a,"caloriesPer100g");if(name==null||name.isBlank()||kcal<0||kcal>10000)return AgentToolResult.failure("VALIDATION_ERROR","A food name and valid calories per 100 g are required.");PrivateFood p=privateFoods.findByUserAndNameIgnoreCase(c.user(),name).orElse(null);if(p==null)privateFoods.save(new PrivateFood(c.user(),name,kcal,null,null,null));else p.refresh(kcal,null,null,null);return AgentToolResult.ok(Map.of("name",name,"caloriesPer100g",kcal));}
  private AgentToolResult updateSettings(AgentContext c,Map<String,Object>a){String timezone=null;Integer target=null;Boolean reports=null;if(a.containsKey("timezone")){try{timezone=ZoneId.of(str(a,"timezone")).getId();}catch(Exception x){return AgentToolResult.failure("VALIDATION_ERROR","Use a valid IANA timezone.");}}if(a.containsKey("calorieTarget")){target=number(a,"calorieTarget");if(target<1200||target>5000)return AgentToolResult.failure("VALIDATION_ERROR","The calorie target must be 1200-5000.");}if(a.containsKey("reportsEnabled")){String value=String.valueOf(a.get("reportsEnabled"));if(!"true".equalsIgnoreCase(value)&&!"false".equalsIgnoreCase(value))return AgentToolResult.failure("VALIDATION_ERROR","reportsEnabled must be true or false.");reports=Boolean.valueOf(value);}UserSettings s=profile(c);if(timezone!=null)s.setTimezone(timezone);if(target!=null)s.setCalorieTarget(target);if(reports!=null)s.setReportsEnabled(reports);return settings(c);}
  private AgentToolResult prepare(AgentContext c,Map<String,Object>a,String type){Long id=number(a,"entryId").longValue();FoodEntry e=entries.findByIdAndUser(id,c.user()).orElse(null);if(e==null)return AgentToolResult.failure("NOT_FOUND","No matching journal entry exists.");String description="DELETE".equals(type)?e.getOriginalMessage():str(a,"description");Integer calories="DELETE".equals(type)?e.getCalories():(a.containsKey("calories")?number(a,"calories"):e.getCalories());if(description==null||description.isBlank()||calories==null||calories<0||calories>10000)return AgentToolResult.failure("VALIDATION_ERROR","An edit needs a non-empty description and calories between 0 and 10000.");if("EDIT".equals(type)&&!Objects.equals(calories,e.getCalories()))return AgentToolResult.failure("VALIDATION_ERROR","Changing nutrition requires deleting and logging the corrected meal so item-level nutrition stays consistent.");Instant now=Instant.now();PendingAgentAction action=pending.findById(c.user().getId()).orElse(null);if(action==null)pending.save(PendingAgentAction.forAction(c.user(),type,id,description,calories,now));else action.replace(type,id,description,calories,now);return new AgentToolResult(false,"REQUIRES_CONFIRMATION",Map.of("entry",summary(e),"proposedDescription",description,"proposedCalories",calories,"action",type),"Ask the user to explicitly confirm this change.");}
  private AgentToolResult getPending(AgentContext c){return pending.findByUserAndExpiresAtAfter(c.user(),Instant.now()).<AgentToolResult>map(p->AgentToolResult.ok(Map.of("action",p.getActionType(),"entryId",p.getEntryId(),"summary",p.getSummary()))).orElse(AgentToolResult.failure("NOT_FOUND","There is no pending change to confirm."));}
  private AgentToolResult confirm(AgentContext c){PendingAgentAction p=pending.findByUserAndExpiresAtAfter(c.user(),Instant.now()).orElse(null);if(p==null)return AgentToolResult.failure("NOT_FOUND","There is no pending change to confirm.");if(!isConfirmation(c.message())||!p.getCreatedAt().isBefore(c.startedAt()))return AgentToolResult.failure("REQUIRES_CONFIRMATION","Show the pending change and wait for a separate explicit confirmation.");FoodEntry e=entries.findByIdAndUser(p.getEntryId(),c.user()).orElse(null);if(e==null){pending.delete(p);return AgentToolResult.failure("NOT_FOUND","That journal entry no longer exists.");}Map<String,Object> changed=summary(e);if("DELETE".equals(p.getActionType()))entries.delete(e);else {e.revise(p.getDescription(),p.getCalories());changed=Map.of("id",e.getId(),"description",p.getDescription(),"calories",p.getCalories(),"eatenAt",e.getEatenAt().toString());}pending.delete(p);dailyStatus.refresh(c.user(),c.chatId());return AgentToolResult.ok(Map.of("action",p.getActionType(),"entry",changed,"today",today(c).data()));}
  private UserSettings profile(AgentContext c){return settings.findById(c.user().getId()).orElseThrow();} private List<FoodEntry> forToday(FoodUser u){ZoneId z=ZoneId.of(settings.findById(u.getId()).orElseThrow().getTimezone());LocalDate d=LocalDate.now(z);return entries.findByUserAndEatenAtBetweenOrderByEatenAtAsc(u,d.atStartOfDay(z).toInstant(),d.plusDays(1).atStartOfDay(z).toInstant());} private Map<String,Object> summary(FoodEntry e){return Map.of("id",e.getId(),"calories",e.getCalories(),"eatenAt",e.getEatenAt().toString(),"description",e.getOriginalMessage());} private String str(Map<String,Object>a,String key){Object v=a.get(key);return v==null?null:String.valueOf(v);} private Integer number(Map<String,Object>a,String key){Object v=a.get(key);if(v==null)throw new IllegalArgumentException();return v instanceof Number n?n.intValue():Integer.parseInt(String.valueOf(v));} private Double decimalNumber(Map<String,Object>a,String key){Object v=a.get(key);return v==null?null:Double.valueOf(String.valueOf(v));} private UUID quoteId(Map<String,Object>a){try{return UUID.fromString(str(a,"quoteId"));}catch(Exception e){return null;}} private JournalIntent.MealItem mealItem(Map<String,Object>a){return new JournalIntent.MealItem(str(a,"name"),decimalNumber(a,"grams"),a.get("totalCalories")==null?null:number(a,"totalCalories"),a.get("caloriesPer100g")==null?null:number(a,"caloriesPer100g"),null,null,null,str(a,"barcode"));} private BigDecimal decimal(Double v){return v==null?null:BigDecimal.valueOf(v);} private boolean isConfirmation(String message){String m=message==null?"":message.trim().toLowerCase(Locale.ROOT);return Set.of("da","confirm","confirmă","confirma","yes").contains(m);} private Map<String,Object> itemSummary(JournalIntent.MealItem i,String source,String confidence){return Map.of("name",i.name(),"grams",i.grams(),"caloriesPer100g",i.caloriesPer100g(),"totalCalories",i.totalCalories(),"source",source,"confidence",confidence);} private boolean validItem(JournalIntent.MealItem item){return item!=null&&item.name()!=null&&!item.name().isBlank()&&item.grams()!=null&&item.grams()>0;} private boolean validCaloriesPer100g(Integer calories){return calories!=null&&calories>0&&calories<=10000;} private JournalIntent.MealItem withCalculatedCalories(JournalIntent.MealItem item){return new JournalIntent.MealItem(item.name(),item.grams(),(int)Math.round(item.grams()*item.caloriesPer100g()/100d),item.caloriesPer100g(),item.proteinGrams(),item.carbsGrams(),item.fatGrams(),item.barcode());} private NutritionMode nutritionMode(Map<String,Object> row){String value=str(row,"nutritionMode");if(value==null||value.isBlank())return NutritionMode.DECLARED;try{return NutritionMode.valueOf(value.toUpperCase(Locale.ROOT));}catch(IllegalArgumentException e){throw new AgentToolFailure(AgentToolResult.failure("VALIDATION_ERROR","nutritionMode must be DECLARED, PACKAGED_MATCH, or AI_ESTIMATE."));}} private String sourceFor(NutritionMode mode){return switch(mode){case DECLARED->"manual";case PACKAGED_MATCH->"open_food_facts_estimate";case AI_ESTIMATE->"ai_estimate";};} private enum NutritionMode { DECLARED, PACKAGED_MATCH, AI_ESTIMATE } private record PersistedItem(JournalIntent.MealItem item,String source,String confidence) {}
}
